// Clean the reviews, then group them into batches for Gemini.
const settings = $('Settings').first().json;
const resp = $input.first().json;
const raw = Array.isArray(resp.reviews) ? resp.reviews : [];

// 1. Clean: drop very short or empty reviews, and exact duplicates
const seen = new Set();
const reviews = [];
for (const r of raw) {
  const text = (r.text || '').replace(/\s+/g, ' ').trim();
  if (text.length < settings.minChars) continue;
  const key = text.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  reviews.push({ id: r.id, text, score: r.score, date: r.date, thumbsUp: r.thumbsUp, appVersion: r.appVersion });
}

// 2. Prompt + JSON schema (Gemini structured output)
const instructions = `You are helping a product team understand why Urban Company customers in India do or do not book another home service within 90 days.
Tag EACH review below. Reviews may be in English, Hindi or Hinglish.
Rules:
- Only use what the review says. Use "unknown" or "not_applicable" when it isn't stated. Never guess a city or household type.
- themes: 1-3 short, specific themes in plain English (e.g. "professional arrived late", "no reminder for next AC service", "booked same cleaner directly"). Avoid vague themes like "bad service".
- evidence: copy the shortest exact phrase from the review that supports your tags.
Return one object per review, using the same id.`;

const enumStr = (values) => ({ type: 'STRING', enum: values });
const schema = {
  type: 'ARRAY',
  items: {
    type: 'OBJECT',
    properties: {
      id: { type: 'STRING' },
      service_category: enumStr(['cleaning', 'ac_appliance_repair', 'plumbing_electrical', 'salon_spa', 'pest_control', 'painting', 'other', 'unknown']),
      journey_stage: enumStr(['need_recognition', 'choosing_provider', 'booking', 'service_day', 'after_service', 'next_need', 'not_applicable']),
      repeat_signal: enumStr(['already_repeat_customer', 'intends_to_return', 'will_not_return', 'switched_to_alternative', 'unclear']),
      alternative_mentioned: enumStr(['local_provider', 'same_professional_directly', 'family_or_neighbour', 'whatsapp_or_society_group', 'competitor_app', 'none']),
      sentiment: enumStr(['positive', 'mixed', 'negative']),
      city: { type: 'STRING' },
      household_type: { type: 'STRING' },
      themes: { type: 'ARRAY', items: { type: 'STRING' } },
      evidence: { type: 'STRING' },
    },
    required: ['id', 'service_category', 'journey_stage', 'repeat_signal', 'alternative_mentioned', 'sentiment', 'themes', 'evidence'],
  },
};

// 3. Batch: one output item = one Gemini request
const out = [];
for (let i = 0; i < reviews.length; i += settings.batchSize) {
  const batch = reviews.slice(i, i + settings.batchSize);
  const listing = batch.map((r) => `id: ${r.id}\nstars: ${r.score}\nreview: ${r.text}`).join('\n---\n');
  out.push({
    json: {
      batchIndex: out.length,
      reviews: batch,
      geminiBody: {
        contents: [{ role: 'user', parts: [{ text: `${instructions}\n\nREVIEWS:\n${listing}` }] }],
        generationConfig: { temperature: 0.2, responseMimeType: 'application/json', responseSchema: schema },
      },
    },
  });
}

if (out.length === 0) {
  throw new Error(`No usable reviews. The service returned ${raw.length} reviews; check the Settings node or the playstore-reviews container logs.`);
}
return out;

// Join Gemini's tags back onto each review. One input item = one batch.
const batches = $('Clean & batch').all();
const collectedAt = new Date().toISOString();
const rows = [];

$input.all().forEach((item, i) => {
  const reviews = batches[i]?.json.reviews ?? [];
  let tags = [];
  let tagError = '';
  try {
    if (item.json.error) throw new Error(typeof item.json.error === 'string' ? item.json.error : JSON.stringify(item.json.error));
    const text = item.json.candidates?.[0]?.content?.parts?.map((p) => p.text || '').join('') ?? '';
    tags = JSON.parse(text);
    if (!Array.isArray(tags)) throw new Error('Gemini did not return a list');
  } catch (e) {
    tagError = String(e.message || e).slice(0, 300);
  }
  const byId = new Map(tags.map((t) => [t.id, t]));

  for (const r of reviews) {
    const t = byId.get(r.id) || {};
    rows.push({
      json: {
        source: 'play_store',
        review_id: r.id,
        date: r.date,
        stars: r.score,
        thumbs_up: r.thumbsUp,
        app_version: r.appVersion,
        text: r.text,
        service_category: t.service_category ?? '',
        journey_stage: t.journey_stage ?? '',
        repeat_signal: t.repeat_signal ?? '',
        alternative_mentioned: t.alternative_mentioned ?? '',
        sentiment: t.sentiment ?? '',
        city: t.city ?? '',
        household_type: t.household_type ?? '',
        themes: Array.isArray(t.themes) ? t.themes.join(' | ') : '',
        evidence: t.evidence ?? '',
        tag_error: t.id ? '' : (tagError || 'missing from Gemini response'),
        batch: i,
        collected_at: collectedAt,
      },
    });
  }
});
return rows;

// Count themes and journey stages, ready to paste into the Notion "Themes & Opportunities" database.
const rows = $input.all().map((i) => i.json).filter((r) => !r.tag_error);
const total = rows.length;
const themes = new Map();

for (const r of rows) {
  for (const raw of (r.themes || '').split(' | ')) {
    const theme = raw.trim().toLowerCase();
    if (!theme) continue;
    const t = themes.get(theme) || { theme, mentions: 0, low_star: 0, stages: {}, categories: {}, example: '' };
    t.mentions += 1;
    if (r.stars <= 2) t.low_star += 1;
    t.stages[r.journey_stage] = (t.stages[r.journey_stage] || 0) + 1;
    t.categories[r.service_category] = (t.categories[r.service_category] || 0) + 1;
    if (!t.example && r.evidence) t.example = r.evidence;
    themes.set(theme, t);
  }
}

const top = (obj) => Object.entries(obj).sort((a, b) => b[1] - a[1])[0]?.[0] ?? '';
return [...themes.values()]
  .sort((a, b) => b.mentions - a.mentions)
  .map((t) => ({
    json: {
      theme: t.theme,
      mentions: t.mentions,
      share_of_reviews_pct: total ? Math.round((t.mentions / total) * 1000) / 10 : 0,
      low_star_share_pct: Math.round((t.low_star / t.mentions) * 1000) / 10,
      main_journey_stage: top(t.stages),
      main_category: top(t.categories),
      example_quote: t.example,
    },
  }));
